before:
/* ---- Newsletter Form Handler ---- */
const nlForm  = document.getElementById('newsletter-email-form');
const nlToast = document.getElementById('newsletter-success-toast');

if (nlForm && nlToast) {
  nlForm.addEventListener('submit', (e) => {
    e.preventDefault();
    nlToast.style.display = 'block';
    nlForm.reset();
    setTimeout(() => { nlToast.style.display = 'none'; }, 6000);
  });
}

after:
.pricing-hero > .container {
  width: 100%;
  min-width: 0;
}

@media (max-width: 640px) {
  .pricing-hero .card-core {
    min-width: 0;
    padding: 1.5rem 1rem !important;
  }

  .pricing-hero .pricing-toggle-container {
    width: 100% !important;
    max-width: 100%;
    gap: 0.25rem;
  }

  .pricing-hero .toggle-label {
    flex-direction: column;
    gap: 0.15rem;
    padding: 0.35rem 0.45rem !important;
    font-size: 0.8rem;
  }

  .pricing-hero .switch {
    flex: 0 0 52px;
    margin: 0 0.25rem !important;
  }

  .pricing-hero .toggle-label .save-badge {
    padding: 0.2rem 0.35rem;
    font-size: 0.625rem;
  }
}
